const chartWidth = 680;
const chartHeight = 560;

const svg = d3
  .select("#bubble-chart")
  .attr("viewBox", `0 0 ${chartWidth} ${chartHeight}`)
  .attr("preserveAspectRatio", "xMidYMid meet");

const tooltip = d3.select("#tooltip");

const formatCompact = (value) => {
  if (!isFinite(value)) return "—";
  const abs = Math.abs(value);
  if (abs >= 1e12) return `${d3.format(".2f")(value / 1e12)}T`;
  if (abs >= 1e9) return `${d3.format(".2f")(value / 1e9)}B`;
  if (abs >= 1e6) return `${d3.format(".2f")(value / 1e6)}M`;
  return d3.format(",.0f")(value);
};

const formatPrice = (value) => {
  if (!isFinite(value)) return "—";
  return `$${d3.format(",.2f")(value)}`;
};

const readableTextColor = (color) => {
  const lab = d3.lab(color);
  return lab.l < 60 ? "#fef7e9" : "#1c1814";
};

const loadHistory = (ticker) =>
  d3
    .csv(`data/indiv-stock/${ticker}.csv`)
    .then((rows) => {
      if (!rows || rows.length === 0) {
        return { ticker, latestClose: NaN, latestDate: null };
      }
      rows.sort((a, b) => new Date(a.Date) - new Date(b.Date));
      const last = rows[rows.length - 1];
      return {
        ticker,
        latestClose: +last.Close,
        latestDate: last.Date,
      };
    })
    .catch(() => ({ ticker, latestClose: NaN, latestDate: null }));

Promise.all([
  d3.csv("data/stock-descriptions.csv"),
  d3.json("data/indiv-stock/index.json"),
]).then(([rawStocks, tickers]) => {
  const tickerSet = new Set(tickers);
  const stocks = rawStocks
    .filter((d) => tickerSet.has(d.ticker))
    .map((d) => ({
      ticker: d.ticker,
      sector: d.sector || "Unknown",
      fullName: d["full name"] || d.fullName || d.name || "",
      marketCap: d.marketCap ? +d.marketCap : NaN,
    }));

  Promise.all(stocks.map((d) => loadHistory(d.ticker))).then(
    (histories) => {
      const historyMap = new Map(histories.map((h) => [h.ticker, h]));
      stocks.forEach((d) => {
        const h = historyMap.get(d.ticker) || {};
        d.latestClose = h.latestClose;
        d.latestDate = h.latestDate;
        d.isETF = !isFinite(d.marketCap);
      });

      render(stocks);
    }
  );
});

function render(stocks) {
  const sectors = Array.from(new Set(stocks.map((d) => d.sector))).sort();
  const palette = d3.schemeTableau10.concat(d3.schemeSet3);
  const color = d3.scaleOrdinal(sectors, sectors.map((d, i) => palette[i % palette.length]));

  const marketCaps = stocks.filter((d) => !d.isETF).map((d) => d.marketCap);
  const radiusScale = d3
    .scaleSqrt()
    .domain([d3.min(marketCaps), d3.max(marketCaps)])
    .range([12, 52]);

  stocks.forEach((d) => {
    d.radius = d.isETF ? 18 : radiusScale(d.marketCap);
  });

  const center = { x: chartWidth / 2, y: chartHeight / 2 };
  const clusterRadius = Math.min(chartWidth, chartHeight) * 0.24;
  const sectorCenters = new Map();
  sectors.forEach((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    sectorCenters.set(sector, {
      x: center.x + clusterRadius * Math.cos(angle),
      y: center.y + clusterRadius * Math.sin(angle),
    });
  });

  const simulation = d3
    .forceSimulation(stocks)
    .force(
      "x",
      d3
        .forceX((d) => sectorCenters.get(d.sector).x)
        .strength(0.08)
    )
    .force(
      "y",
      d3
        .forceY((d) => sectorCenters.get(d.sector).y)
        .strength(0.08)
    )
    .force("collide", d3.forceCollide((d) => d.radius + 1.5))
    .force("charge", d3.forceManyBody().strength(-22))
    .force("center", d3.forceCenter(center.x, center.y));

  const nodes = svg
    .append("g")
    .attr("class", "nodes")
    .selectAll("g")
    .data(stocks)
    .enter()
    .append("g")
    .attr("class", "node")
    .attr("data-ticker", (d) => d.ticker);

  nodes
    .append("circle")
    .attr("r", (d) => d.radius)
    .attr("fill", (d) => color(d.sector));

  nodes
    .append("text")
    .text((d) => d.ticker)
    .style("fill", (d) => readableTextColor(color(d.sector)));

  nodes
    .on("click", (event, d) => {
      selectTicker(d.ticker);
    })
    .on("mouseover", (event, d) => {
      if (d.isETF) return;
      tooltip
        .html(
          `<strong>${d.ticker}</strong><br/>${d.fullName}<br/><em>${d.sector}</em>` +
            (isFinite(d.latestClose)
              ? `<br/><span>Latest close (${d.latestDate}): ${formatPrice(d.latestClose)}</span>`
              : "")
        )
        .classed("visible", true);
      moveTooltip(event);
    })
    .on("mousemove", (event, d) => {
      if (d.isETF) return;
      moveTooltip(event);
    })
    .on("mouseout", () => {
      tooltip.classed("visible", false);
    });

  simulation.on("tick", () => {
    nodes.attr("transform", (d) => `translate(${d.x},${d.y})`);
  });

  const legend = d3
    .select("#legend")
    .selectAll(".legend-item")
    .data(sectors)
    .enter()
    .append("div")
    .attr("class", "legend-item");

  legend
    .append("span")
    .attr("class", "legend-swatch")
    .style("background", (d) => color(d));

  legend
    .append("span")
    .attr("class", "legend-label")
    .text((d) => d);

  const tableData = stocks.slice().sort((a, b) => {
    if (!isFinite(a.marketCap) && !isFinite(b.marketCap)) return 0;
    if (!isFinite(a.marketCap)) return 1;
    if (!isFinite(b.marketCap)) return -1;
    return d3.descending(a.marketCap, b.marketCap);
  });

  const rows = d3
    .select("#stock-table tbody")
    .selectAll("tr")
    .data(tableData)
    .enter()
    .append("tr")
    .attr("data-ticker", (d) => d.ticker)
    .on("click", (event, d) => {
      selectTicker(d.ticker);
    });

  rows
    .append("td")
    .text((d) => d.ticker);

  rows
    .append("td")
    .text((d) => d.fullName);

  rows
    .append("td")
    .text((d) => d.sector);

  rows
    .append("td")
    .attr("class", "market-cap")
    .text((d) => formatCompact(d.marketCap));

  function selectTicker(ticker) {
    nodes.classed("selected", (d) => d.ticker === ticker);
    rows.classed("selected", (d) => d.ticker === ticker);

    const rowEl = rows.filter((d) => d.ticker === ticker).node();
    if (rowEl) {
      rowEl.scrollIntoView({ block: "center", behavior: "smooth" });
    }
  }
}

function moveTooltip(event) {
  tooltip
    .style("left", `${event.pageX + 12}px`)
    .style("top", `${event.pageY - 24}px`);
}
JS"}

